{
  "goal": "Analyze all quarterly sales CSV files: detect data-quality issues, repair recoverable ones, revalidate, compute per-quarter statistics, merge results, run a quality review, and emit a consolidated Markdown report with an evidence log.",
  "steps": [
    {
      "name": "inspect_files",
