        "output": {
          "name": "schema_report",
          "typeName": "Record",
          "fields": [
            {"name": "columns", "typeName": "List"},
            {"name": "row_count", "typeName": "Integer"},
            {"name": "issues", "typeName": "List"}
          ]
        }
      },
      "output": {
        "name": "schema_reports",
        "typeName": "List<Record>",
        "fields": [
          {"name": "columns", "typeName": "List"},
          {"name": "row_count", "typeName": "Integer"},
          {"name": "issues", "typeName": "List"}
        ]
      }
    },
    {
      "name": "analyze_and_repair",
      "kind": "foreach",
      "description": "For each file detect issues, repair recoverable ones, revalidate, and compute quarterly statistics.",
      "over": "inputs",
      "body": {
        "name": "repair_and_stats",
        "kind": "primitive",
        "capability": "execute_python",
        "code": "import csv, json, statistics, os
path = '${item}'
with open(path, newline='') as f:
    reader = csv.reader(f)
    rows = list(reader)
header = rows[0] if rows else []
data = rows[1:] if len(rows) > 1 else []
issues = []
repaired = []
seen = set()
numeric_cols = []
for i, col in enumerate(header):
    vals = [r[i] for r in data if i < len(r) and r[i] != '']
    num = 0
    for v in vals:
        try:
            float(v)
            num += 1
        except:
            pass
    if num / max(len(vals), 1) >= 0.5:
        numeric_cols.append(i)
for idx, r in enumerate(data):
    if len(r) != len(header):
        issues.append(f"row {idx}: column count mismatch ({len(r)} vs {len(header)})")
        continue
    key = tuple(r)
    if key in seen:
        issues.append(f"row {idx}: duplicate")
        continue
    seen.add(key)
    cleaned = list(r)
    for c in numeric_cols:
        v = cleaned[c]
        if v == '' or v.upper() == 'NULL' or v.upper() == 'NA':
            cleaned[c] = '0'
            issues.append(f"row {idx}: missing numeric in {header[c]} -> 0")
        else:
            try:
                float(v)
            except:
                cleaned[c] = '0'
                issues.append(f"row {idx}: type error in {header[c]} '{v}' -> 0")
    repaired.append(cleaned)
n = len(data)
numeric_vals = {}
for c in numeric_cols:
    vals = []
    for r in repaired:
        try:
            vals.append(float(r[c]))
        except:
            pass
    if vals:
        numeric_vals[header[c]] = {"sum": round(sum(vals), 2), "mean": round(sum(vals)/len(vals), 2), "min": round(min(vals), 2), "max": round(max(vals), 2), "count": len(vals)}
stats = numeric_vals
with open(path, newline='') as f:
    r2 = csv.reader(f)
    header2 = next(r2)
    row2 = list(r2)
repaired_header = header
repaired_rows = [repaired_header] + repaired
quarter = 'Q1' if 'q1' in path.lower() else 'Q2' if 'q2' in path.lower() else 'Q3' if 'q3' in path.lower() else 'Q4'
result = {"quarter": quarter, "file": path, "issues": issues, "issue_count": len(issues), "repaired_row_count": len(repaired), "original_row_count": n, "stats": stats, "columns": header}
env["analysis_result"] = result",
        "output": {
          "name": "analysis_result",
          "typeName": "Record",
          "fields": [
            {"name": "quarter", "typeName": "String"},
            {"name": "file", "typeName": "String"},
            {"name": "issues", "typeName": "List"},
            {"name": "issue_count", "typeName": "Integer"},
            {"name": "repaired_row_count", "typeName": "Integer"},
